tools.example:
img = ExampleData[{"TestImage", "House"}];
pts = ImageKeypoints[img, MaxFeatures -> 200];
Show[img, Graphics[{Red, PointSize[0.008], Point[pts]}]]

img = ExampleData[{"TestImage", "House"}];
rot = ImageRotate[img, 0.2];
{p1, p2} = ImageCorrespondingPoints[img, rot];
Length[p1]

img = ExampleData[{"TestImage", "House"}];
{err, tf} = FindGeometricTransform[img, ImageRotate[img, 0.15]];
tf[{100, 100}]

img = ExampleData[{"TestImage", "House"}];
shifted = ImageTransformation[img, # + {0.05, 0.02} &];
aligned = ImageAlign[img, shifted];
ImageAdjust@ImageDifference[img, aligned]

a = ExampleData[{"TestImage", "House"}];
b = ImageTransformation[a, # + {0.01, 0} &];
flow = First@ImageDisplacements[{a, b}];
ListStreamPlot[flow]

img = ExampleData[{"TestImage", "Lena"}];
boxes = FindFaces[img];
HighlightImage[img, Rectangle @@@ boxes]

img = ExampleData[{"TestImage", "Coins"}];
c = ComponentMeasurements[Binarize[img], "Centroid"];
HighlightImage[img, Point[Values[c]]]
